package au.aumanet.app;
import android.content.Context;import android.graphics.Bitmap;import org.json.*;
import java.awt.image.BufferedImage;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
import javax.imageio.*;import javax.imageio.stream.*;

/** Real JPEG/file/hash/chunk tests. Desktop ImageIO is an explicit Android codec boundary. */
public final class GroupImageLimitsTest {
 static int checks,tests;static Path root;static final String SELF="AA".repeat(32),ID="b".repeat(32),GROUP="c".repeat(32);
 interface Work{void run()throws Exception;}static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}static Exception rejects(Work work,String why)throws Exception{try{work.run();}catch(Exception refused){checks++;return refused;}throw new AssertionError(why);}
 static byte[] jpeg(int w,int h,float quality,long seed)throws Exception{BufferedImage image=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);Random random=new Random(seed);for(int y=0;y<h;y++)for(int x=0;x<w;x++)image.setRGB(x,y,random.nextInt(0x1000000));ByteArrayOutputStream bytes=new ByteArrayOutputStream();ImageWriter writer=ImageIO.getImageWritersByFormatName("jpeg").next();try(ImageOutputStream target=new MemoryCacheImageOutputStream(bytes)){writer.setOutput(target);ImageWriteParam options=writer.getDefaultWriteParam();options.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);options.setCompressionQuality(quality);writer.write(null,new IIOImage(image,null,null),options);target.flush();}finally{writer.dispose();}return bytes.toByteArray();}
 static JSONObject input(byte[] bytes,int w,int h)throws Exception{return new JSONObject().put("mimeType","image/jpeg").put("width",w).put("height",h).put("byteLength",bytes.length).put("sha256",GroupTextWire.hash(bytes)).put("dataBase64",Base64.getEncoder().encodeToString(bytes));}
 static byte[] padded(byte[] jpeg,int length)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(jpeg,0,2);int remaining=length-jpeg.length;byte[] sentinel="PRIVATE_METADATA_SENTINEL".getBytes(StandardCharsets.US_ASCII);while(remaining>0){int size=Math.min(remaining,65537);if(remaining-size>0&&remaining-size<4)size-=4;if(size<4)throw new IllegalArgumentException("Invalid padding fixture");out.write(255);out.write(254);out.write((size-2)>>>8);out.write((size-2)&255);byte[] comment=new byte[size-4];System.arraycopy(sentinel,0,comment,0,Math.min(comment.length,sentinel.length));out.write(comment);remaining-=size;}out.write(jpeg,2,jpeg.length-2);return out.toByteArray();}
 static void boundaries()throws Exception{
  tests++;check(GroupTextWire.MAX_IMAGE==1048576&&GroupTextWire.MAX_IMAGE_EDGE==2048,"central transmitted limits");check(GroupTextWire.MAX_IMAGE_BASE64==1398104,"base64 ceiling includes padding");check(GroupTextWire.CHUNK==4096&&GroupTextWire.MAX_ENVELOPE==8192,"transport bounds unchanged");
  GroupTextWire.Image maximum=new GroupTextWire.Image(2048,2048,1048576,"A".repeat(64),"B".repeat(64));check(GroupTextWire.Image.parse(maximum.json()).bytes==1048576,"exact cap/dimension accepted");
  rejects(()->new GroupTextWire.Image(2049,2048,1048576,"A".repeat(64),"B".repeat(64)),"oversize edge denied");rejects(()->GroupTextWire.Image.parse(maximum.json().put("byteLength",1048577)),"oversize bytes denied");
  GroupImageFiles files=new GroupImageFiles(new Context(root.resolve("limits-input").toFile()));byte[] exact=padded(jpeg(512,512,.65f,1),GroupTextWire.MAX_IMAGE);JSONObject prepared=input(exact,512,512);check(prepared.getString("dataBase64").length()==GroupTextWire.MAX_IMAGE_BASE64,"exact input base64 bound");GroupImageFiles.Prepared clean=files.normalize(prepared);check(clean.bytes.length<GroupTextWire.MAX_IMAGE,"exact input accepted and normalized");check(!new String(clean.bytes,StandardCharsets.ISO_8859_1).contains("PRIVATE_METADATA_SENTINEL"),"native re-encode strips input JPEG comment metadata");
  rejects(()->files.normalize(new JSONObject(prepared.toString()).put("byteLength",1048577)),"over-cap prepared declaration denied");rejects(()->files.normalize(new JSONObject(prepared.toString()).put("dataBase64","A".repeat(GroupTextWire.MAX_IMAGE_BASE64+1))),"over-cap base64 denied before decode");rejects(()->files.normalize(input(jpeg(2049,8,.65f,2),2049,8)),"actual over-edge JPEG rejected before full decode");
  GroupImageFiles.Prepared wide=files.normalize(input(jpeg(2048,640,.4f,3),2048,640));check(wide.image.width==2048&&wide.bytes.length>262144&&wide.bytes.length<=GroupTextWire.MAX_IMAGE,"actual new edge and above-old-limit output accepted");
 }
 static void fallback()throws Exception{
  tests++;GroupImageFiles files=new GroupImageFiles(new Context(root.resolve("limits-fallback").toFile()));byte[] source=jpeg(1280,1280,.6f,4);check(source.length<=GroupTextWire.MAX_IMAGE,"fallback fixture fits transmitted input budget");Bitmap.qualities.clear();int recycled=Bitmap.recycled;GroupImageFiles.Prepared normalized=files.normalize(input(source,1280,1280));check(normalized.bytes.length>262144&&normalized.bytes.length<=GroupTextWire.MAX_IMAGE,"real fallback remains above old cap and within new cap");check(Bitmap.qualities.size()>1&&Bitmap.qualities.get(0)==85&&Bitmap.qualities.get(1)==72,"real quality85 overflow takes bounded72 fallback");check(Bitmap.recycled==recycled+1,"decoded bitmap recycled after success");
  byte[] difficult=jpeg(2048,2048,.24f,5);check(difficult.length<=GroupTextWire.MAX_IMAGE,"incompressible prepared fixture fits input budget");Bitmap.qualities.clear();recycled=Bitmap.recycled;Exception denied=rejects(()->files.normalize(input(difficult,2048,2048)),"all bounded qualities must deny oversized output");check(Bitmap.qualities.equals(Arrays.asList(85,72,58,44)),"all and only four fallback qualities attempted");check(Bitmap.recycled==recycled+1,"decoded bitmap recycled after failure");check(GroupTextErrors.message(denied).equals("Normalized image exceeds 1 MiB; choose a smaller image"),"friendly limit error is allowlisted");
 }
 static void resumeAndQuota()throws Exception{
  tests++;byte[] bytes=padded(jpeg(512,512,.65f,6),GroupTextWire.MAX_IMAGE);GroupTextWire.Image manifest=new GroupTextWire.Image(512,512,bytes.length,GroupTextWire.hash(bytes),GroupTextWire.hash(bytes));GroupTextStore.Scope scope=new GroupTextStore.Scope(GROUP,SELF);Context context=new Context(root.resolve("limits-resume").toFile());GroupImageFiles files=new GroupImageFiles(context);int at=0;
  while(at<32*GroupTextWire.CHUNK){int end=Math.min(bytes.length,at+GroupTextWire.CHUNK);at=files.append(scope,SELF,ID,manifest,at,Arrays.copyOfRange(bytes,at,end),()->true);}int committed=at;File partial=new File(files.directory,GroupImageFiles.reference(scope.key,SELF,ID)+".part");try(FileOutputStream tail=new FileOutputStream(partial,true)){tail.write(new byte[]{1,2,3});}files=new GroupImageFiles(context);check(files.partial(scope,SELF,ID,committed)==committed&&partial.length()==committed,"restart truncates uncommitted tail to durable offset");int chunks=32;
  while(at<bytes.length){int end=Math.min(bytes.length,at+GroupTextWire.CHUNK);at=files.append(scope,SELF,ID,manifest,at,Arrays.copyOfRange(bytes,at,end),()->true);chunks++;}check(chunks==256&&at==1048576,"exact1MiB completes in unchanged4096-byte chunks");check(Arrays.equals(files.read(scope,SELF,ID,manifest),bytes),"resumed content hash and all JPEG bytes preserved");check(files.available(scope,SELF,ID,manifest),"exact-cap JPEG validates from private storage");
  File complete=new File(files.directory,GroupImageFiles.reference(scope.key,SELF,ID)+".jpg");try(FileOutputStream extra=new FileOutputStream(complete,true)){extra.write(0);}final GroupImageFiles reopened=files;rejects(()->reopened.read(scope,SELF,ID,manifest),"oversized local file rejected without unbounded read");
  GroupImageFiles quota=new GroupImageFiles(new Context(root.resolve("limits-quota").toFile()));check(GroupImageFiles.QUOTA==64L*1024*1024,"quota scales to64MiB");File reserved=new File(quota.directory,"F".repeat(64)+".jpg");try(RandomAccessFile sparse=new RandomAccessFile(reserved,"rw")){sparse.setLength(GroupImageFiles.QUOTA-GroupTextWire.MAX_IMAGE);}check(quota.room(GroupTextWire.MAX_IMAGE)&&!quota.room(GroupTextWire.MAX_IMAGE+1),"remaining quota admits exact cap only");quota.put(scope,SELF,ID,bytes,manifest);check(quota.room(0)&&!quota.room(1),"exact quota reached without overrun");rejects(()->quota.put(scope,SELF,"d".repeat(32),bytes,manifest),"next image denied at quota without eviction");check(quota.directory.listFiles().length==2,"quota rejection leaves existing files intact");
 }
 public static void main(String[] args)throws Exception{root=Paths.get(args[0]);boundaries();fallback();resumeAndQuota();System.out.println(new JSONObject().put("status","pass").put("testCount",tests).put("assertionCount",checks).put("bitmapBoundary","Real desktop ImageIO quality-aware JPEG encoding; Android Bitmap codec acceptance remains physical"));}
}
